def crear_roles(apps, schema_editor):
    Group = apps.get_model('auth', 'Group')
    Permission = apps.get_model('auth', 'Permission')
    ContentType = apps.get_model('contenttypes', 'ContentType')

    # Modelos principales de Talking Hands que vamos a controlar
    modelos = ['modulo', 'leccion', 'ejercicio', 'senna', 'logro', 'perfil']
    permisos_admin = []
    permisos_aprendiz = []

    for modelo_nombre in modelos:
        content_type, _ = ContentType.objects.get_or_create(
            app_label='th_app',
            model=modelo_nombre
        )
        p_view, _ = Permission.objects.get_or_create(
            codename=f'view_{modelo_nombre}',
            content_type=content_type,
            defaults={'name': f'Can view {modelo_nombre}'}
        )
        p_add, _ = Permission.objects.get_or_create(
            codename=f'add_{modelo_nombre}',
            content_type=content_type,
            defaults={'name': f'Can add {modelo_nombre}'}
        )
        p_change, _ = Permission.objects.get_or_create(
            codename=f'change_{modelo_nombre}',
            content_type=content_type,
            defaults={'name': f'Can change {modelo_nombre}'}
        )
        p_delete, _ = Permission.objects.get_or_create(
            codename=f'delete_{modelo_nombre}',
            content_type=content_type,
            defaults={'name': f'Can delete {modelo_nombre}'}
        )

        # Administrador tiene todos los permisos (CRUD completo)
        permisos_admin.extend([p_view, p_add, p_change, p_delete])

        # Aprendiz tiene permisos de lectura (consulta)
        if modelo_nombre in ['modulo', 'leccion', 'ejercicio', 'senna', 'logro']:
            permisos_aprendiz.append(p_view)

    # Grupo 1: Administrador (Todos los permisos)
    admin_group, _ = Group.objects.get_or_create(name='Administrador')
    admin_group.permissions.set(permisos_admin)

    # Grupo 2: Aprendiz (Solo consulta / aprendizaje)
    aprendiz_group, _ = Group.objects.get_or_create(name='Aprendiz')
    aprendiz_group.permissions.set(permisos_aprendiz)


